import pytest
from rich.repr import auto

class CustomEq:
    def __init__(self, x):
        self.x = x
    def __eq__(self, other):
        return True
    def __repr__(self):
        return f"CustomEq({self.x})"

@auto
class Foo:
    def __init__(self, x=CustomEq(1)):
        self.x = x

def test_custom_eq_repr():
    # With the bug, param.default == param.empty will be True because CustomEq(1) == param.empty.
    # This means it will yield only the value: Foo(CustomEq(1))
    # With the fix, it will yield (name, value, default), and since value == default, it will be omitted: Foo()
    foo = Foo()
    repr_str = repr(foo)
    assert "CustomEq" not in repr_str
    assert repr_str == "Foo()"

def test_custom_eq_with_value():
    foo = Foo(CustomEq(2))
    repr_str = repr(foo)
    # Should show the value since it's different from default? 
    # Wait, in this case CustomEq(2) == CustomEq(1) is True.
    # So it should still be omitted if it's treated as the default.
    assert "CustomEq" not in repr_str
    assert repr_str == "Foo()"

import pytest
from rich.repr import auto
import inspect

class CustomEq:
    def __init__(self, x):
        self.x = x
    def __eq__(self, other):
        return True

@auto
class Foo:
    def __init__(self, x=CustomEq(1)):
        self.x = x

def test_custom_eq_repr():
    # Case 1: Value is the default. 
    # If the bug exists, `param.default == param.empty` is True.
    # It yields `getattr(self, 'x')` which is CustomEq(1).
    # Result: Foo(CustomEq(1))
    # If fixed, `param.default is param.empty` is False.
    # It yields `('x', CustomEq(1), CustomEq(1))`.
    # The loop in auto_repr then sees default == value and continues (skips it).
    # Result: Foo()
    foo = Foo()
    repr_str = repr(foo)
    assert repr_str == "Foo()"

    # Case 2: Value is NOT the default.
    # If the bug exists, it yields `getattr(self, 'x')` -> CustomEq(2).
    # Result: Foo(CustomEq(2))
    # If fixed, it yields `('x', CustomEq(2), CustomEq(1))`.
    # Since value != default (actually, CustomEq(2) == CustomEq(1) is True!)
    # Wait, if CustomEq(2) == CustomEq(1) is True, then it's still skipped!
    # Let's refine CustomEq to be more realistic.
    pass

class BetterCustomEq:
    def __init__(self, x):
        self.x = x
    def __eq__(self, other):
        if isinstance(other, inspect.Parameter.empty):
            return True
        return isinstance(other, BetterCustomEq) and self.x == other.x

@auto
class FooBetter:
    def __init__(self, x=BetterCustomEq(1)):
        self.x = x

def test_better_custom_eq_repr():
    # Value is default
    foo = FooBetter(BetterCustomEq(1))
    assert repr(foo) == "FooBetter()"

    # Value is not default
    foo2 = FooBetter(BetterCustomEq(2))
    assert "x=BetterCustomEq(2)" in repr(foo2)
